INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '80''s Overdrive', '80''S OVERDRIVE is a 2D pixel art racing game, designed to take you back in time to when 8 and 16 bit consoles and arcade games ruled the world. Compete against opponents in career mode to unlock new races, buy new cars, and upgrade them with state-of-the-art technologies! Try your skill in time attack mode and see how far you can get in this race against the clock! Create your own tracks with built-in track generator and easily share them with your friends!' FROM games WHERE igdb_id = 58717 ON CONFLICT (game_id, language_code) DO NOTHING;
