INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No Heroes Here', 'No Heroes Here is a 2-4 multiplayer cooperative frenetic Castle Defense game where you and your friends must defend castles against hordes of enemies. Craft, craft more, craft some more, load your cannon and FIRE! In this frantic game for the survival of the kingdom of Noobland, players need to cooperate and coordinate at all times in order to achieve their goal!' FROM games WHERE igdb_id = 54979 ON CONFLICT (game_id, language_code) DO NOTHING;
