INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Franz Kafka Videogame', 'The Franz Kafka Videogame is an original puzzle/adventure game inspired by the writings of Franz Kafka. The protagonist named K., gets a sudden offer of employment and this event changes his life forcing him to make a distant voyage. To his surprise, the world beyond his homeland appears to be not as normal as he would think. Together with K., you will experience an atmosphere of absurdity, surrealism, and total uncertainty.' FROM games WHERE igdb_id = 26239 ON CONFLICT (game_id, language_code) DO NOTHING;
