INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Knight''s Dungeon', 'Knight''s Dungeon is a puzzle game where you must solve word, number, color, push-block, and music puzzles to advance through the dungeon. You use an in-game journal to automatically record information as you find it. Also features a handful of expansive side-games separate from the original campaign, such as a hilltop mansion mystery or an ocean adventure complete with a health and game-over system.' FROM games WHERE igdb_id = 360631 ON CONFLICT (game_id, language_code) DO NOTHING;
