INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Exiled', 'The Exiled is the world''s first Open World Survival Arena. The Exiled rests on the three defining pillars; Meaningful Conflict, Skill-Based Combat, and Constantly Changing Worlds. We will throw you into a dark fantasy prison valley. You start each game with nothing but your wits and your PvP skills. Over the course of weeks and months you will explore this world, grow stronger and learn to survive.' FROM games WHERE igdb_id = 26241 ON CONFLICT (game_id, language_code) DO NOTHING;
