INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MX Nitro: Unleashed', 'MX Nitro: Unleashed invites you to blaze into motocross racing nirvana! Tear through new urban environments at blistering speeds including mean streets and a bustling subway system. Freestyle through the air with 55 death-defying tricks to earn Nitro speed boosts in your battles against new hardcore bosses. Crash your way through re-imagined levels packed with adrenaline-pumping ramps and obstacles. MX Nitro: Unleashed expands upon the original MX Nitro with new tracks, new bosses, and new outfits. The game also includes several improvements from the original including improved visuals, from rider textures to the water, and new Easy difficulty mode.' FROM games WHERE igdb_id = 133400 ON CONFLICT (game_id, language_code) DO NOTHING;
