INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('edge-of-existence', 74189, '2017-12-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobabi.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/iokfc3hq9klnbgcfbzlj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Edge Of Existence', 'Edge Of Existence. Is a throw back to the Classics of RTS where you can build up your base and build up your massive army. Ranging from Ground units , Air Units and Sea Units. We also take you on a story base RTS where a faction has a meaning to the map or why its in-game. We are a balance focus on PvP, PvE and Story/Campaign. We don''t want focus on the PvP Competitive or ESports side of things. Since i feel like RTS games are ment for Story and Campaign. We also understand that alot of players don''t even want to PvP so they expect great PvE so we hope to have the right Balance between all those 3 core gameplays. We want make a RTS thats plays from the Classics but has the Graphics of New Gens for the players that haven''t experienced the great RTS games we had in the pass.' FROM games WHERE igdb_id = 74189 ON CONFLICT (game_id, language_code) DO NOTHING;
