INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Cave VR', 'A VR experience that will put yourself in a situation you wouldn''t want to be in real life. Feel yourself inside a dangerous cave and try to walk through the only possible exit. A short and really thrilling experience that will test your vertigo and claustrophobia. Enjoy the views while you can with the only tool you have: a spotlight. Be brave and get into The Cave! Specially designed also for arcade saloons, this experience will make the difference.' FROM games WHERE igdb_id = 74179 ON CONFLICT (game_id, language_code) DO NOTHING;
