INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Missileman Origins', 'Missileman Origins is a retro-esque action-platformer set in a world where robots and humans co-exist as civilians. Missileman himself is a humble bot that wishes he could, one day, become a hero. He knows he has the potential to be one, but it''s never fully realized just how capable he would be.' FROM games WHERE igdb_id = 33034 ON CONFLICT (game_id, language_code) DO NOTHING;
