INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Echoes of the Fey Episode 0: The Immolation', 'Imagine being the only survivor of an explosion that kills thousands of people. That is the fate of Sofya Rykov. And survival is just the beginning of her tale... Episode 0: The Immolation is a free, standalone chapter in the Echoes of the Fey adventure game/visual novel series.' FROM games WHERE igdb_id = 29634 ON CONFLICT (game_id, language_code) DO NOTHING;
