INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Didgery', 'Didgery is a unique merger of card and puzzle that blends fun explosive action with thoughtful  strategy. Sit back and relax in Zen Mode, or put your skills to the ultimate test by battling the forces of  evil in Nightmare Mode. Change up the rules with Special Cards, uncover a fantastical back-story of  biblical proportions, and immerse yourself in the relaxing zen-like atmosphere. Didgery is a fun,  addictive, and fresh experience for both puzzle and card aficionados.' FROM games WHERE igdb_id = 33867 ON CONFLICT (game_id, language_code) DO NOTHING;
