INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead By Murder', '“Dead By Murder”, is a murder mystery strategy game, where the user plays as a police detective and must solve a series of homicide cases. The game has a look and feel of a black and white comic book. It is set in Los Angeles in 1945 and all the characters have the faces of golden age Hollywood stars.' FROM games WHERE igdb_id = 74144 ON CONFLICT (game_id, language_code) DO NOTHING;
