INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Mummy: Dark Universe Stories', 'The legend of The Mummy continues in this globe trotting supernatural mystery that picks up where the movie leaves off. Choose your fate in an immersive visual tale filled with dynamic comic book style illustrations that spin you through an action-packed adventure. Unlock hidden secrets in every interactive episode as you trigger unique puzzles and uncover multiple endings. Every spellbinding turn reveals a high-stakes decision that changes the outcome of the storyline.' FROM games WHERE igdb_id = 36858 ON CONFLICT (game_id, language_code) DO NOTHING;
