INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Prison Boys', 'The Prison Boys is a visual novel with adventure game elements taking place at the end of the Taisho period in Japan with some of the events mentioned in the game based on real events. Players take the role of Tetsu Akatsuki, a member of a special police force serving in a 12-story prison. Having found his superior hanged in his room, Tetsu decides to investigate the circumstances of his death and uncover the mysteries hidden in the prison walls.
