INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cyberoque', 'The game takes place in 2215. Suddenly terrible news has come from the outskirts of the solar system: our civilization was attacked by the alien armies. A terrible war begins, humanity is surrounded, enemy space ships press the earth''s army. The module in a body of the best robot-ship is sent to the space base of newcomers near the satellite of Saturn where main enemy forces are concentrated...' FROM games WHERE igdb_id = 59255 ON CONFLICT (game_id, language_code) DO NOTHING;
