INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Party', 'Mini Party started as a game for groups and parties, but now has a single player mode too! 2-8 players can connect their devices locally to play a series of 5 minigames and see who comes out on top! Players use their devices to tap, tilt, touch, shake, rotate, move, and MORE in the 10+ (and counting) minigames to beat their friends and family! You don''t use an internet connection because Mini Party is meant to encourage social interaction with your friends and family! If you don''t have anyone around or just wanna compete against yourself, play the single player mode and see how high you can score on your own!' FROM games WHERE igdb_id = 83857 ON CONFLICT (game_id, language_code) DO NOTHING;
