INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uncle Sad Bedroom', 'Go to work or get an internship with anarcho-syndicalists. Go to other galaxies and dimensions. Fly a living ship around. Fight mother nature''s aunt. Slide down an apocalyptic spa. Snort moon rocks with your landlord. Ride the train. Get evicted. Talk about nothing in particular. Play an operating system instrument.' FROM games WHERE igdb_id = 128208 ON CONFLICT (game_id, language_code) DO NOTHING;
