INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Men of Freedom', 'Men of Freedom is an award-winning first-person shooter game featuring fights between the English forces and the patriots in the south of Iran near the Persian Gulf during WWI (1910-1915). These patriots fought under the leadership of a man called Raiis-Ali Delvari. The Game story is based on real historical events happening during that time. The game includes 10 big levels with different gameplays (Action, Stealth, Support, Run) in various environments.' FROM games WHERE igdb_id = 394927 ON CONFLICT (game_id, language_code) DO NOTHING;
