INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('puzzle-pests', 174366, '2017-08-28', NULL, NULL, NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzle Pests', 'Puzzle Pests is a fiendishly addictive bug-based puzzle game. The aim of Puzzle Pests is simple - clear all the fleas off the game board by blowing them up, sending them through trap doors or matching four fleas of the same color in a straight line or a square formation. But beware! New fleas are being born all the time so you have to keep up with the population growth. Puzzle Pests is packed with puzzles and challenges to keep you coming back for more. Have you got what it takes to beat the pesky fleas? Hours and hours of insect fun. With three different game modes and cartoon-style graphics, you’ll never get tired of playing Puzzle Pests. Solve 100 puzzle levels, see if you can deal with increasingly more difficult levels in the Round Robin mode or test your mettle under time pressure.' FROM games WHERE igdb_id = 174366 ON CONFLICT (game_id, language_code) DO NOTHING;
