INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alter Ego', 'Alter Ego is a text-based interactive fiction game where players live a complete life from birth to death, making choices through over a thousand multiple-choice questions that determine their character''s path. Players decide whether to grow up confident or troubled, befriend or fight bullies, find romance, pursue marriage and family, or build a business empire, with substantially different experiences available for male and female characters. Originally published in 1986 for Commodore 64, MS-DOS, Apple II, and Macintosh, this updated edition maintains the original content while featuring an improved interface and bug fixes from the classic pick-a-path gamebook style.' FROM games WHERE igdb_id = 363225 ON CONFLICT (game_id, language_code) DO NOTHING;
