INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bsl-winter-games-challenge', 87331, '2017-12-03', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/wabfuqtaaqsfse4kht2y.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/q43u8egiv9lji35tmxji.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BSL Winter Games Challenge', 'BSL Winter Games Challenge has four (4) fast pace exciting tracks that are challenging with dramatic turns and length of course. Test your Speed and Time Skills against your favorite Country Team in the upcoming Winter Games. Choose between Tilt or Controller Input to best fits your style of play. Play either the Bobsled, Skeleton, or Luge in this 3 in 1 game. Try and beat your high scores and speed records each time you play. Twenty-four (24) teams to choose from and 3 different Camera Angles to enhance your gaming skills. This 3 games in 1 challenge play will keep you engaged each time you play. The game also includes a Holiday Bonus Track.
