INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monumental Failure', 'Monumental Failure is a historically (in)accurate physics-based monument construction simulator. The game empowers you to recreate some of the world''s most impressive architectural feats using incredible, and hard-to-believe, construction techniques. From the great ring at Stonehenge, to the genius of the ancient Roman aqueduct, will you have what it takes to re-create these feats of engineering?' FROM games WHERE igdb_id = 29940 ON CONFLICT (game_id, language_code) DO NOTHING;
