INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('arcade-style-bot-ball-shooting-multiplayer-game', 28462, '2017-06-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/tylvcouyrny4gxzmr2cy.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ip4k01pvd57ztes7mabo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arcade Style Bot Ball Shooting Multiplayer Game', 'We have just released 2 days ago a new FPS game, but we have tried to make it look and shoot different, than what is average on this type of games. Its a shooters game, but instead of bullets that you cannot see or interact with, shoots balls, that bounce and do sparks all around what it hits. Because the game is still in development, there are some bugs and some issues to be improved, but in general its very playable. We got it in LAN and Multiplayer versions, so we would love to have the chance that somebody who loves this type of games review it, and give us feedback, excellent or horrible, but the opinion of an gameris vital to improve the game or stop it.' FROM games WHERE igdb_id = 28462 ON CONFLICT (game_id, language_code) DO NOTHING;
