INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Matryona no Yuube', 'Matryona is a pretty, adorable girl. That’s what her mother tells her, what her father tells her. She is the ideal daughter that anyone could wish for… But is the reality of the situation truly as sweet as it seems? As they say, everyone has their secrets…' FROM games WHERE igdb_id = 150556 ON CONFLICT (game_id, language_code) DO NOTHING;
