INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yono and the Celestial Elephants', 'Yono and the Celestial Elephant is a grand adventure, featuring carefully designed puzzles, treasure hunts, a sprinkling combat and a world full of people. Play as a young elephant tasked to save a world he’s never seen before, and explore the rich history of a kingdom where humans, zombies and robots live side by side.' FROM games WHERE igdb_id = 55197 ON CONFLICT (game_id, language_code) DO NOTHING;
