INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'One Sole Purpose', 'One Sole Purpose is an action packed science fiction first person shooter with a horror twist. It is developed to give the player a fun and engaging combat experience and bring them an immersive world with a memorable plot. The player has access to many different types of abilities that they would have to use to survive the unforgiving combat.' FROM games WHERE igdb_id = 27572 ON CONFLICT (game_id, language_code) DO NOTHING;
