INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Albion Online', 'Albion Online is a sandbox MMORPG set in an open medieval fantasy world. The game features a player-driven economy where nearly every item is player-crafted. Combine armor pieces and weapons suited to your playstyle in a unique, classless "you are what you wear" system. Explore the world, take on other adventurers in thrilling battles, conquer territories, and build a home.' FROM games WHERE igdb_id = 19698 ON CONFLICT (game_id, language_code) DO NOTHING;
