INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Dust: The Book of Earth (VR)', 'Star Dust: The Book of Earth is a VR sci-fi shooting game developed by Beijing Skylens Technology Co., Ltd. using Unreal Engine4, featuring amazing cinematic visual effects. In the game, you will explore awe-inspiring, mysterious galaxies, experience the spectacular scenes of Earth’s destruction, and engage in warfare on a scale never seen before – and all from an immersive first-person perspective. Take control of huge mechs with your own hands and immerse yourself in fierce space battles. The splendor of magnificent galaxies, giant spaceships, and diverse weapons combine to create a real and thrilling VR experience you’ll never forget. In the game, players use VR handles to control a giant mech in battle.' FROM games WHERE igdb_id = 29931 ON CONFLICT (game_id, language_code) DO NOTHING;
