INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taiko no Tatsujin: Drum Session', 'Enjoy the cult classic arcade rhythm game from Japan in the comfort of your own home! Play to the beat using your own drum with a wide variety of new songs and challenge your friends to prove who has the best taiko skills. Enjoy beloved characters on your journey to become a legendary taiko drummer! Enjoy a casual and competitive Taiko arcade experience on the PlayStation 4 through standard rhythm mode and ranked versus play.' FROM games WHERE igdb_id = 76643 ON CONFLICT (game_id, language_code) DO NOTHING;
