INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A Magical Tale: Cavern Crawler', 'In "A Magical Tale: Cavern Crawler", you have been given the task to complete each of the caverns located in each area! These cavern''s contain 15 levels, filled with both action elements and puzzles! All areas have a distinct environment from the likes of lava, sand, ice or water. They all collaborate into a full quest with over 90+ levels overall to cater to your cavern crawling need!' FROM games WHERE igdb_id = 134995 ON CONFLICT (game_id, language_code) DO NOTHING;
