INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game Tengoku CruisinMix Special', 'Game Tengoku CruisinMix Special is an enhanced port of Jaleco''s classic 90s vertically scrolling shooting game, mixing cute characters, a game world parodying a wide range of gaming tropes and history, tight controls, refined mechanics and eggplants?! CruisinMix features both the console original and the exclusive Arcade Mode + in a retro game fan''s dream combination!' FROM games WHERE igdb_id = 112414 ON CONFLICT (game_id, language_code) DO NOTHING;
