INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Slither Snake IO 2018', 'Slither.io is a massively multiplayer online video game available for iOS, Android, and web browsers, developed by Steve Howse. Players control an avatar resembling a worm, which consumes multicolored pellets, both from other players and ones that naturally spawn on the map in the game, to grow in size. The objective of the game is to grow the longest worm in the server. Slither.io is similar in concept to the popular 2015 web game Agar.io and is reminiscent of the classic arcade game Snake.' FROM games WHERE igdb_id = 101372 ON CONFLICT (game_id, language_code) DO NOTHING;
