INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Assassin''s Creed: Origins - Dawn of the Creed Legendary Edition', 'Be among the firsts to dive into the Assassin’s Creed Origins universe with this never seen before Collector’s Edition. Featuring a 73cm high-end resin statue of Bayek, a protector of Egypt whose personal story will lead to the creation of the Assassin’s Brotherhood, and his eagle Senu, this exceptional Collector’s Edition is ready to be shipped exclusively on the Ubisoft Store with only 999 units Worldwide.' FROM games WHERE igdb_id = 39047 ON CONFLICT (game_id, language_code) DO NOTHING;
