INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kakuchou Shoujo-kei Trinary', 'Kakuchou Shoujo-kei Trinary is a mobile RPG developed by Gust and Toei Animation. Released in 2017, it blends real-time battles with an interactive narrative that unfolds through live-updated anime episodes and character communication features. Players assist five girls fighting digital threats known as "Phenomenon" while forming bonds through daily conversations and decisions. The game was part of a multimedia project and ran until August 31, 2018.' FROM games WHERE igdb_id = 346771 ON CONFLICT (game_id, language_code) DO NOTHING;
