INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Uniqlo × Boxboy!', 'UNIQLO × BOXBOY! is web browser based video game made in collaboration with Uniqlo, a Japanese clothing company, and Game Developers HAL Laboratory. The game stars QBBY of the BOXBOY! series who can make boxes from his body which will occasionally feature the UNIQLO logo on them. The game features 3 Level Packs which change based on which day of the week it is with said Level Packs being split between Easy, Normal, and Difficult. Level Packs have you playing 3 levels in a row with there being a total of 63 different levels split across all Seven days.' FROM games WHERE igdb_id = 345414 ON CONFLICT (game_id, language_code) DO NOTHING;
