INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Final Storm', 'A cross-platform twin-stick shooter and bullet hellish game. It''s designed as a pickup game you can play in 3-5 minutes when you just wanna shoot a lot of bullets and dodge just as many. Survive as many waves as possible and pickup a few power-ups along the way (.. ahem... you''ll need them). Enemies increase in number and difficulty as waves progress.' FROM games WHERE igdb_id = 74661 ON CONFLICT (game_id, language_code) DO NOTHING;
