INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Help Annie', '"Help Annie" is an adventurous interactive mystery thriller in the style of a messenger app game. YOU are Annie''s last and only hope, the choices YOU make may save Annette Lewis who is – instead of spending a once-in-a-lifetime vacation – confronted with a series of mysterious events. Caught up in the shadows of her past, it’s now a matter of life and death.' FROM games WHERE igdb_id = 239232 ON CONFLICT (game_id, language_code) DO NOTHING;
