INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mage the Ascension: Refuge', 'Set in modern-day Sweden, Mage: The Ascension: Refuge by critically-acclaimed author Karin Tidbeck, lets you experience today''s social and political upheavals while awakening to the power of True Magick - the ability to shape reality itself through your force of belief. Many will try to recruit you into a secret war where human consensus itself is the battlefield. Your actions and choices will have profound consequences on the world and people around you... assuming madness and paradox doesn''t claim you first.' FROM games WHERE igdb_id = 27423 ON CONFLICT (game_id, language_code) DO NOTHING;
