INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2Dark', 'From Frédérick Raynal, the creator of Alone in the Dark and pioneer of survival-horror, 2Dark is a grim journey of stealth and courage into the heart of corruption. Plagued by a string of child abductions, darkness hangs over the once-picturesque city of Gloomywood like a curse. As former detective Mr. Smith, use your cunning to infiltrate six bastions of cruelty. Uncover the secrets of the deranged psychopaths within, seek retribution for their crimes, and bring the children to safety.' FROM games WHERE igdb_id = 26847 ON CONFLICT (game_id, language_code) DO NOTHING;
