INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yume Nyaki', 'Yume Nyaki is a Yume Nikki fangame created for the 2017 Dream Diary Jam. Nyasuki has a dream about being asked by a mysterious person known as Cheru to aid an "Administrator" in some way, and to not harm the tree that Cheru is standing in front of. Then Nyasuki wakes up, and his adventure begins. Nyasuki''s main goal is finding effects in the dream world.' FROM games WHERE igdb_id = 201639 ON CONFLICT (game_id, language_code) DO NOTHING;
