INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Take the Veil', 'Take The Veil is an English Yume Nikki fangame made for the 2017 Dream Diary Jam. You play as a psychic goat named Ulysses as he arrives at an abandoned campsite. After encountering some strange crosses, he finds an empty caravan to stay in. From here, he enters the Fourth Dimension with the goal of pulling the ethereal crosses. This game contains dialogue and there are a number of NPCs the player can talk to. There are no effects to be gotten.' FROM games WHERE igdb_id = 201638 ON CONFLICT (game_id, language_code) DO NOTHING;
