INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sachin Saga Cricket Champions', 'From fans of epic cricket games to fans of Tendulkar, fantasy players can now live cricket as the legendary Master Blaster. Introducing Top 3D Mobile Cricket Game. Enjoy high-performance graphics and realistic motion-captured animations of criket in this sports game. Relive some of the most iconic moments from criket history in console-quality play. Experience top IPL T20 cricket battles while recreating master strokes of the Cricket God. Featuring multiple modes of play in this sports games - One-days, Tests, IPL T20, domestic, Premier League, World Cup criket– this epic cricket game is all geared up to bring you endless entertainment.' FROM games WHERE igdb_id = 202685 ON CONFLICT (game_id, language_code) DO NOTHING;
