INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kingdom Hearts 0.2: Birth by Sleep - A Fragmentary Passage', 'A short sequel to Kingdom Hearts Birth By Sleep that partially takes place during the events of the first Kingdom Hearts, A fragmentary passage gets its name from a hidden ending to BBS and tells the story of Master Aqua''s ten-year journey through the Realm of Darkness. 0.2 acts as a prologue to the upcoming Kingdom Hearts III, and also as a demo of Kingdom Hearts traversal, combat, and graphics in Unreal Engine 4 as it will appear in KH3. This game is only playable as part of the collection Kingdom Hearts HD 2.8 Final Chapter Prologue.' FROM games WHERE igdb_id = 26676 ON CONFLICT (game_id, language_code) DO NOTHING;
