INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tri Focuser: Outside the Traditional World', 'A Touhou fangame developed by Shijimi Nono, Ido and Raichu, with gameplay similar to the official Touhou games Shoot the Bullet and Double Spoiler. Much like those two, this game also brings back a variety of characters, but here they are from games developed by the Kaisendo circle prior to this game''s release: The Last Comer, Mystical Power Plant, Riverbed Soul Saver, and Book of Star Mythology.' FROM games WHERE igdb_id = 246673 ON CONFLICT (game_id, language_code) DO NOTHING;
