INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bombastic Cars', 'Bombastic Cars is a fast-paced, action packed car game in which you can choose from a variety of crazy weapons, maps and cars! You can block paths with huge, fiery tornadoes that suck your opponents in the air, stun them with icy projectiles or simply hail bombs on your foes and more. There is only one goal: Destroy all of your enemys in order to win!' FROM games WHERE igdb_id = 74601 ON CONFLICT (game_id, language_code) DO NOTHING;
