INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Big Fear of Heights Experience', 'The Big Fear of Heights Experience is a horrifying experience. People can''t help turning back midway. It''s an extreme test of courage 200 meters above the ground! Even if you are unable to take even one step out of fear a refund will not be issued. Please be aware that the experience will end as soon as your foot steps off the plank.' FROM games WHERE igdb_id = 52002 ON CONFLICT (game_id, language_code) DO NOTHING;
