INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SnarfQuest Tales, Episode 1: The Beginning', 'In this point-and-click adventure game from the mind of Larry Elmore, you play as Snarf, a Zeetvah from Zeetville on an epic quest for fame and fortune. (Mostly fortune.) Can you help Snarf earn the gold, help the woman, and win his place on the throne?' FROM games WHERE igdb_id = 32689 ON CONFLICT (game_id, language_code) DO NOTHING;
