INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Warpaint', 'Warpaint is a physics boardgame where you command an army of dwarves and launch catapults. Strike fear into your opponent with your customized, painted army. Victory is won through superior tactical positioning and siege dexterity. Climb the rankings and brag about your battle born brains. The game is easy to learn, quick to play, and maintains tension at a relaxed pace.' FROM games WHERE igdb_id = 29358 ON CONFLICT (game_id, language_code) DO NOTHING;
