INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Howard Phillips Lovecar', 'A top-down driving shooter. It''s like Devil Daggers + GTA1 (Kill Frenzy!). You try to kill lovecraftian monstrosities with a shotgun (and more) while driving a car. Also, lots of evil cultists to mow down. It''s a short, intense score-attack affair. Stop The Great Old Ones - or die trying!' FROM games WHERE igdb_id = 38781 ON CONFLICT (game_id, language_code) DO NOTHING;
