INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infinity Fall', 'Immerse yourself in the starship Aphelion''s vast and unforgiving underbelly. You are Doctor Rupert Grouch, hounded by his own creation, DAVE. Survive time-based, combat and stealth trials, all in zero gravity.  An experience uniquely suited to and built for VR.' FROM games WHERE igdb_id = 55349 ON CONFLICT (game_id, language_code) DO NOTHING;
