INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Packing Up the Rest of Your Stuff on the Last Day at Your Old Apartment', 'It''s a hot, hot August 31st in Chicago. You''ve got both fans going on you. The bare mattress feels so cool on your back... A train rumbles by. At least you won''t have to do this again for another year. And it will be fall soon. The playlist on your Ogg Player repeats.' FROM games WHERE igdb_id = 83070 ON CONFLICT (game_id, language_code) DO NOTHING;
