INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Come Up', 'At 14 years old, teenagers are sent out to explore distant space. Encased in small, cold cells to survive the hundreds of years it takes to reach their destination, their bodies age 4 to 5 years while their minds do not age at all. Your mission is to explore, survive and excel through the planet you''ve been sent to scan for life. You are starting from the bottom. Can you make the come up?  The Come Up is a 3D Metroidvania for PC and VR that seeks to fully utilize 3 dimensional space by pushing level design and gameplay vertically as well as horizontally.' FROM games WHERE igdb_id = 116587 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 116587 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
