INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wiz Mud', 'An abandoned MUD (Multi User Dimension), unearthed by hackers in the year 2017 where you play as a wizard in a once lively MMO world. The new tenants of WizMud have taken to tossing priceless artifacts (old junk) from this forgotten MMO into the fishing pond, along with its conventions.' FROM games WHERE igdb_id = 213132 ON CONFLICT (game_id, language_code) DO NOTHING;
