INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kiteboard Hero', 'No matter what game-mode you play, there’s plenty of rewards to be earned, improving your rider’s ability to jump higher, hang for longer and pull-off all types of moves. Now it’s just a question of whether you’ve got the skills to be a Kiteboard Hero!' FROM games WHERE igdb_id = 175339 ON CONFLICT (game_id, language_code) DO NOTHING;
