INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '2MD VR Football', '2MD VR Football is a room-scale two-minute drill VR arcade experience that allows players to become the virtual quarterback they were born to be! Draw your own plays and customize up to 8 teams before taking them on the road to victory. Featuring fully interactive motion tracking, customizable plays, two-minute drill gameplay, unlockable teams, Steam Leaderboards & Achievements, an action packed bonus game, and more. Compatible with HTC VIVE and Oculus Rift.' FROM games WHERE igdb_id = 68572 ON CONFLICT (game_id, language_code) DO NOTHING;
