INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unknightly', 'Unknightly is a medieval VR stealth game designed from the ground up for virtual reality. You play the role of a former member of the "Knight''s Order". You have been banished from the kingdom never to return again, on the charge of "Unknightly" behavior. Hungry for revenge and fortune you seek training with the local thieve''s guild, with the plan of returning to rob the "Knight''s Order" of all of its valuable belongings!' FROM games WHERE igdb_id = 75520 ON CONFLICT (game_id, language_code) DO NOTHING;
