INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lost Memories Dot Net', 'Lost Memories Dot Net is a game about chatting and building websites as a teenage girl in 2004. You play as 14 year old Nina, chatting with your online friend Kayla about a middle school love triangle, and building your blog between messages. You explore the online world Nina occupies, downloading images to decorate your blog as the drama at school unfolds.' FROM games WHERE igdb_id = 139539 ON CONFLICT (game_id, language_code) DO NOTHING;
