INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Human Spirit Agency: A Salvageable Tragedy', 'Human Spirit Agency ~ A Salvageable Tragedy is a free Chinese fangame developed in RPGMaker XP by Bawu Team, heavily inspired by the Ace Attorney Investigations games. Players take on the role of Youmu Konpaku as she solves a series of grisly murders throughout Gensokyo and unwraps the tragedy connecting it all.' FROM games WHERE igdb_id = 382678 ON CONFLICT (game_id, language_code) DO NOTHING;
