INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amon', 'Follow Amon, the God of Air, on his quest to connect a world of puzzling optical illusions using Virtual Reality. Look around, move around and play around with ancient 3D scanned sculptures from museums around the world. Be sure to put your headphones on when putting together the historic pieces, as Amon is built with Binaural Audio to help you solve the puzzles. It will be an epic journey that moves you. Literally.' FROM games WHERE igdb_id = 75934 ON CONFLICT (game_id, language_code) DO NOTHING;
