INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'South Park: The Fractured but Whole - Remote Control Coon Mobile Bundle', 'Ubisoft presents the RC Coon Mobile, Cartman’s Coon-themed big wheel. An Amazon exclusive, this collectible is app-enabled, allowing it to turn freely, spin in place and move forward or backwards. The Coon’s personality comes to life with lines from the game!
