INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('yggdrasil-chronicles-a-tale-of-cindrivia', 233340, '2017-11-20', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sckpm0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yggdrasil Chronicles: A Tale of Cindrivia', 'Hundred years ago, The Illuminati Order, originally formed by a demon named Lucifer, plunged the whole world into Chaos. With his mighty power, he slowly corrupted this living world, driving the humanity to an extinction. Fortunately, six remarkable warriors, calling themselves Warriors of The Holy Alliance, possessed the power of faith and justice, stood against The Illuminati as the last hope of Cindrivia. With the help of the Heavenly Artifacts sent down by Aina The Goddess of Night, they finally put an end to Lucifer and his Illuminati Order. The world of Cindrivia then found peace again for decades. Many years have passed, and now The Illuminati Order is about to raise again, lead by a mysterious wizard so-called Ryan The Illuminator. The existence of Cindrivia and even The Yggdrasil Tree is in danger one more time.' FROM games WHERE igdb_id = 233340 ON CONFLICT (game_id, language_code) DO NOTHING;
