INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mutiny!!', '"Mutiny!! is set in a world of fantasy, and adventure. A realm where airships can sail among the clouds as well as the sea, entering the flogiston to journey to other planes. There’s treasure spread out over many planes if you’re brave or curious enough to find it! At the bottom of the sea or within mysterious ruins, protected by curious animated guardians. The world of Mutiny!! is in every way ‘fun’, silly and sexy as you imagine!"' FROM games WHERE igdb_id = 83823 ON CONFLICT (game_id, language_code) DO NOTHING;
