INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Trivia Vault: 1980''s Trivia', 'Welcome to the Trivia Vault contestant! Play as a contestant in a gameshow called Trivia Vault 1980''s Trivia and bring your thinking hat. Answer questions about 1980''s trivia as quickly as you can, the faster you answer the higher the cash value. Correct answers lock in the digit code for the vault, 10 correct answers cracks the vault and awards bonus cash.' FROM games WHERE igdb_id = 54342 ON CONFLICT (game_id, language_code) DO NOTHING;
