INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Yu-No: A Girl Who Chants Love at the Bound of this World', 'Yu-No: A Girl Who Chants Love at the Bound of this World is a Japanese-style adventure game, also known as a visual novel, originally released in 1996 for the NEC PC-98, and later ported to the Sega Saturn and Windows. In 2017 a remake was produced for the Playstation 4 and Playstation Vita, with completely redrawn HD graphics and rearranged music, while maintaining the same story and game structure. The 2019 Nintendo Switch port included these new features as well.' FROM games WHERE igdb_id = 11816 ON CONFLICT (game_id, language_code) DO NOTHING;
