INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Until None Remain VR', 'Until None Remain is a futuristic multiplayer first person shooter in a Battle Royale or Last Man Standing format. Matches pit weaponless players against one another in a death match that continues until only one player remains. Players must rush to acquire weapons, armor, or specialty items such as jet packs, or traps. Scale walls or objects using magnetized gloves, jet around the arena in a jet pack, and interact with an environment that includes turrets, explosive containers, noxious gases, and more!' FROM games WHERE igdb_id = 68365 ON CONFLICT (game_id, language_code) DO NOTHING;
