INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Game of Thrones: Conquest', 'Developed by Turbine, the MMO strategy mobile game puts players at the head of their own powerful House, with the ultimate goal of navigating the dangerous political landscape of Westeros and claiming the Iron Throne. Players will see some familiar faces from the hit HBO show as they play the game, including Daenerys Targaryen, Tyrion Lannister, and Jon Snow. Game of Thrones: Conquest is coming to the App Store and Google Play later this year.' FROM games WHERE igdb_id = 56967 ON CONFLICT (game_id, language_code) DO NOTHING;
