INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nature Treks VR', 'NEW: With the latest updates, you are now free to explore and have the ability to shape your environment!  Create and immerse yourself into a world of peace, calm and relaxation. Watch your surroundings react to the soundscape or play without music to experience the soothing sounds of nature all around you. Nature Treks VR is alive with animals, birds and other life. Watch butterflies fluttering within arms'' reach or elephants, rhinos, foxes, boars, bears and more in their natural environments.' FROM games WHERE igdb_id = 29552 ON CONFLICT (game_id, language_code) DO NOTHING;
