INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Homescapes', 'Homescapes is a mobile game developed by Playrix that combines match-3 puzzle mechanics with home renovation simulation. In the game, players join the main character, Austin the butler, in his quest to help his parents restore their old family mansion to its former glory. The gameplay primarily revolves around completing match-3 puzzle levels to earn stars, which are then used to progress in the renovation process.' FROM games WHERE igdb_id = 68316 ON CONFLICT (game_id, language_code) DO NOTHING;
