INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Channel', 'Dream Channel is a ''choose your own adventure'' VR series about gangsters who buy and sell dreams on the black market. Players enter a VR world (The Dream Channel) and soon discover that their dreams have been stolen too! The starting sector for the story is the DJ sector where DJs play sets from the virtual night clubs - seamlessly monetised using Gaze Coin.' FROM games WHERE igdb_id = 75929 ON CONFLICT (game_id, language_code) DO NOTHING;
