INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sekai de Ichiban Kanashii Egao', 'The protagonist, Gaku Serizawa, is a pachinko addict who goes to a pachinko parlor every day. One day, he happens to stop by a park on his way home from pachinko and meets a mysterious girl who wants sweets. His world starts to change little by little as he comes to know her.' FROM games WHERE igdb_id = 357525 ON CONFLICT (game_id, language_code) DO NOTHING;
