INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Jammers', 'Arcade + SHMUP + Bullet Time + Rogue-ish. 1-4 player co-op shooter where getting to the venue is the real adventure. Retro Mashup of Gauntlet2 / Galaga / Battle Toads / Hotline Miami / Nuclear Throne and lots of geek-culture references. Randomized gear, bosses, rules and missions. Challenging, yet approachable for newcomers and quick for couch play.' FROM games WHERE igdb_id = 27651 ON CONFLICT (game_id, language_code) DO NOTHING;
