INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Troll and I', 'A Mythical Adventure: Befriend the fabled Troll and embark on a journey through the Nordic wilderness as two outcasts struggling to survive. Choose your combat style based on the situation. Become the Troll and stomp hunters with your massive feet, or smash them with your giant fists. Switch to Otto for quick, nimble attacks and fast traversing.' FROM games WHERE igdb_id = 26503 ON CONFLICT (game_id, language_code) DO NOTHING;
