INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Watch Out', 'Watch out, is intended to be a "I gotta kill 5-10 minutes somehow"-game. It''s a Arcade racing game where you only objective is to get as high score as possible. The only thing you have to look for, is your time, where you get time added each road you complete, and the pedestrians by not hitting them.' FROM games WHERE igdb_id = 55290 ON CONFLICT (game_id, language_code) DO NOTHING;
