INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Moe Mekuri SP', 'The goal of this game is to turn all the panels to face up. You can choose the level stage from EASY, NORMAL, and HARD. However, in order to play the NORMAL stage, you need to have passed all the EASY stages, and to play the HARD stage, all the NORMAL stages. Once you passed a stage, all the images from that stage are added to the GALLERY.' FROM games WHERE igdb_id = 28693 ON CONFLICT (game_id, language_code) DO NOTHING;
