INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pyre', 'A party-based RPG/visual novel/sports game hybrid wherein the player, dubbed the Reader for their literacy by the group of scavengers who discovers them, is sent in exile to a lawless wasteland called the Downside and has to lead their ever-growing party of misfits to locations wherein many similar parties compete in Rites in order to attain freedom and be absolved of their crimes.' FROM games WHERE igdb_id = 18822 ON CONFLICT (game_id, language_code) DO NOTHING;
