INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Operation Apex', 'A virtual reality underwater adventure for the Vive in which you, a citizen scientist, take control of a research rig in order to learn about the current state of the oceans. As you begin to learn how to study the seas you are witness to one of the largest great white sharks ever seen. Moments later, your mission is clear - travel through the kelp, down the continental shelf and out in the open ocean to find and scan the mysterious shark.' FROM games WHERE igdb_id = 75498 ON CONFLICT (game_id, language_code) DO NOTHING;
