INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fariwalk: The Prelude', 'The world where humanity is almost gone. A few remaining people search for each other amongst monsters, common inhabitants of the Earth. However, this story is about a child who is going to obtain something very important. Fariwalk: The Prelude is a short prologue to The Fariwalk game. This horror adventure will introduce you to the sad, withering world of the game.' FROM games WHERE igdb_id = 74997 ON CONFLICT (game_id, language_code) DO NOTHING;
