INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Avenger Bird', 'Avenger Bird is a platform side-scroller game with pixel-art graphics, but your hero isn''t just a regular hero. You are playing a bird that can flap it''s tiny wings to fly and glide for a limited distances. It''s a retro inspired 16-bit era game with innovative and challenging fly/glide mechanic.' FROM games WHERE igdb_id = 30491 ON CONFLICT (game_id, language_code) DO NOTHING;
