INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Night in the Woods', 'Night In The Woods is an adventure game heavily focused on story, characters and exploration, with some platforming to get around town. Mae''s a cat so the roofs and ledges and powerlines are all her playground, and she''s not the only one up there by a long shot. You''ll also be doing various activities and interacting with the world in different ways, getting to know the townspeople, hanging out with friends, exploring Possum Springs inside and out, and venturing into the surrounding areas.' FROM games WHERE igdb_id = 10148 ON CONFLICT (game_id, language_code) DO NOTHING;
