INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Biomydra', 'Play as Snow, a solo agent sent on a mission to Biomydra to report on the fate of a fellow officer. Explore colorful environments in this toe curling action-adventure game as you unfurl the staggering truth about the breathing planet you are walking on and the twisted people who sent you there. With the help of her magnetic arm, solve brilliant puzzles and fight your way through daunting enemies to reach your ultimate goal.' FROM games WHERE igdb_id = 30749 ON CONFLICT (game_id, language_code) DO NOTHING;
