INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Sexy Brutale', 'Set during a single, endlessly-looping day within "The Sexy Brutale" - a stately English mansion converted into a bizarre casino and named by the enigmatic Marquis - players take on the role of elderly priest Lafcadio Boone. To progress, Boone must hide, watch and learn the colorful stories of the other guests at the ball in order to save them from grisly deaths at the hands of the mansion’s staff.' FROM games WHERE igdb_id = 22783 ON CONFLICT (game_id, language_code) DO NOTHING;
