INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Abstract Arena', 'Abstract Arena is a top-down action-shooter game set in a completely abstract context. Up to 6 different ships can clash in the Arena, taking advantage of all of the unique and balanced skills each of them owns. Fast, precise, powerful: the gameplay is easy to learn but hard to master, adaptable to many play styles thanks to the variety of situations the player is brought to encounter.' FROM games WHERE igdb_id = 33632 ON CONFLICT (game_id, language_code) DO NOTHING;
