INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Resident Evil 7: Biohazard', 'Resident Evil 7: Biohazard is the first game of the Resident Evil series to switch from 3rd-person to fully 1st-person perspective. A complete refresh of gameplay systems simultaneously propels the survival horror experience to another level. It is as much horror as it is survival, boosting up scare elements and minimizing downright shooting action. The game allows use of Sony''s PSVR Headset to play in VR mode.' FROM games WHERE igdb_id = 19562 ON CONFLICT (game_id, language_code) DO NOTHING;
