INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dragon Ball VR: Master the Kamehameha', '"This power... absolutely incredible! An unprecedented Kamehameha experience!! Enter the world of Dragonball with our innovative new VR technology and equipment, and experience firsthand what its really like to generate a Kamehameha. Feel your body shake from the intensity! Train with Goku himself and learn to generate your own Kamehameha! Test your Kamehameha in battle with friends! Generate more power than the others and blow them all away!!! For the first time ever in VR! Buy your own VR Senzu beans (sold separately) and experience eating them in the VR world."' FROM games WHERE igdb_id = 49116 ON CONFLICT (game_id, language_code) DO NOTHING;
