INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fire Emblem Echoes: Shadows of Valentia', 'In 1992, the second game in the Fire Emblem series, Fire Emblem Gaiden, launched exclusively in Japan. Now, for the first time, fans outside of Japan will get a taste of this classic game on the Nintendo 3DS family of systems. Fire Emblem Echoes: Shadows of Valentia is inspired by the 1992 original, reimagined on a grander scale. Every aspect of the Fire Emblem Gaiden game''s presentation has been updated, along with the game being fully voiced. Fire Emblem Echoes: Shadows of Valentia recreates classic Fire Emblem gameplay with a modern twist, mixing in exploration of dungeons crawling with enemies."' FROM games WHERE igdb_id = 26840 ON CONFLICT (game_id, language_code) DO NOTHING;
