INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Super ComboMan: Smash Edition', 'Super Comboman is a modern Action game, inspired by classic fighting games set in a gorgeous 2D hand drawn sticker world! Super Comboman takes skill and patience in order to figure out how to survive swarms of enemies. Bust mad combos across 16 action-packed levels as Struggles, the comic book nerd with a sick arsenal of flashy moves who is obsessed with his favorite super hero, SUPER COMBOMAN. Action fans, fighting fans, and air combo fans...this one’s for you.' FROM games WHERE igdb_id = 32674 ON CONFLICT (game_id, language_code) DO NOTHING;
