INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Love 2: Kuso', 'Kuso, the sequel to Love, is a reductive platforming game with a retro aesthetic and a focus on a challenging difficulty. You find yourself in a minimalist world and with only the ability to run and jump, as well as the option to leave a checkpoint on any solid ground. Make your way through acid, long jumps, disappearing platforms, bouncers, and swinging axes.' FROM games WHERE igdb_id = 29777 ON CONFLICT (game_id, language_code) DO NOTHING;
