INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'the Peter Navarre Crecy Evaluation', 'The tragedy of the situation is that while being one of the most valuable objects in Kaisar''s posession, it got stolen in most peculiar circumstances. To the untrained eye it would seem that the Evaluation simply vanished from this layer, ceasing to exist in a split of a second. However, the smell of electricity left in the air after that occurence told another story.' FROM games WHERE igdb_id = 77729 ON CONFLICT (game_id, language_code) DO NOTHING;
