INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Darkest Dungeon: Crimson Edition', 'Darkest Dungeon: Crimson Edition contains Darkest Dungeon plus Darkest Dungeon: The Crimson Court DLC. Darkest Dungeon is a challenging gothic roguelike turn-based RPG about the psychological stresses of adventuring. Recruit, train, and lead a team of flawed heroes through twisted forests, forgotten warrens, ruined crypts, and beyond. You''ll battle not only unimaginable foes, but stress, famine, disease, and the ever-encroaching dark. Uncover strange mysteries, and pit the heroes against an array of fearsome monsters with an innovative strategic turn-based combat system.' FROM games WHERE igdb_id = 91323 ON CONFLICT (game_id, language_code) DO NOTHING;
