INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pinstripe', 'Pinstripe is an emotionally charged adventure about Hell created entirely by a one-man team over the course of five years. Play as Teddy, an estranged ex-minister forced to venture through the frozen afterlife in search of Bo, his three year old daughter, and her perverse kidnapper. Discover the dark secrets of Teddy''s past, and confront his sleazy, demonic nemesis, Mr. Pinstripe.' FROM games WHERE igdb_id = 20454 ON CONFLICT (game_id, language_code) DO NOTHING;
