INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Oblivion Tesseract VR', 'Oblivion Tesseract is a VR game, performed with FPS mode, which differs from the old-school TD games. Your target is to protect the Tesseract and to survive from fierce monsters, with different types of guns, grenades and immense mass energy turrets! Tesseract can absorb the abilities of the bosses you defeated! Explore the Tesseract’s history as a brave guardian!' FROM games WHERE igdb_id = 29708 ON CONFLICT (game_id, language_code) DO NOTHING;
