INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bit City', 'Build your own Bit City! Start from a tiny town and grow to a thriving metropolis in this city building idle game from the creators of Tiny Tower. Collect profits and invest in upgrades that keep your city growing. Fill your city with new types of cars, planes and ships. Unlock cool new buildings, including famous landmarks to customize the look of your city. What are you waiting for? Start building YOUR own Bit City now!' FROM games WHERE igdb_id = 174681 ON CONFLICT (game_id, language_code) DO NOTHING;
