INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Basement', 'The Basement is a first person horror environment exploration game. You as the player awake in a dark and lost basement. You don''t know where you are or even why you are at this point. It is on you to explore this lost place. So grab your flashlight from the table and try to get out!' FROM games WHERE igdb_id = 51462 ON CONFLICT (game_id, language_code) DO NOTHING;
