INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhythm Rush!', 'Play your own songs to three different game modes on, newly updated to, eight different maps, or fight the three unlockable bosses! Play on four different difficulties to get a range of challenge! Keep track of your stats and compare them to your friends! Earn all the achievements by playing and getting better at it! Play more songs on harder difficulties to rank up faster! It is easy to grasp but hard to master! Play any song you want by just dragging them into a folder! The game reads MP3s, OGGs, and WAVs!' FROM games WHERE igdb_id = 29019 ON CONFLICT (game_id, language_code) DO NOTHING;
