INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hex: Origins', 'Hex: Origins is a casual puzzle game based on a complete hexagon themed colorful experience. Enjoy a refreshing, calming and original experience, which is extremely easy to pick up but hard to master as you progress in the game. Across the multitude of game modes and levels you will encounter, you must place pieces composed of anywhere from 2 to 10 and more hexagons, each using up to 6 different colors.' FROM games WHERE igdb_id = 63738 ON CONFLICT (game_id, language_code) DO NOTHING;
