INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wrecked', 'See how long you can survive on an island full of wildlife - and even wilder people! Compete for resouces with a new 2-handed control system that doubles the ways you can interact with the world around you - putting the power to create or destroy in your own hands. Explore the island''s 10 unique locations long enough to solve the mystery of why you''re there - and what lies on the other side of the ocean...' FROM games WHERE igdb_id = 357053 ON CONFLICT (game_id, language_code) DO NOTHING;
