INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bystander', 'Bystander is an opportunity to become an agent for tracking the network during totalitarianism. Your task is to search among other people''s correspondence on the network those that contradict the current laws, copies of which you will receive by fax. Follow the new laws, look for the hidden meaning in each phrase and, of course, report violations, to the glory of the great Arstotska!' FROM games WHERE igdb_id = 75827 ON CONFLICT (game_id, language_code) DO NOTHING;
