INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tetsudou Nippon! Rosen Tabi: Aizu Tetsudou‑hen', 'A train simulation game from Sonic Powered''s "Japanese Rail Sim" series. This title is exclusive to Japan, and was the last game in the series released for the Nintendo 3DS. In this entry, you can operate the Aizu Railway''s "AT-700" and "AT-100" train models through a 57.4 km trip from Nishiwakamatsu Station to Aizu Kogen Ozeguchi Station, on Aizu Railway''s Aizu Line.' FROM games WHERE igdb_id = 221946 ON CONFLICT (game_id, language_code) DO NOTHING;
