INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BlazBlue Revolution Reburning', '“BlazBlue RR - Real Action Game” is a revolutionary 2D side-scrolling fighting game on mobile platform. With its exquisite 2D graphics, orthodox fighting experience and character voices contributed by famous Japanese voice actors, this game is truly a work of art and will leave players awestruck. Another remarkable feature of the game is its unique control system, stylish yet easy to master, this brand new touch-and-swipe control system will surely bring the ultimate fighting game experience to the players.' FROM games WHERE igdb_id = 38977 ON CONFLICT (game_id, language_code) DO NOTHING;
