INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mini Sports Collection', 'Mini Sports Collection focuses on the fun part of each sport throwing you straight into the heart of each one! Bat in Baseball, shoot clay targets in Skeet Shooting, take down opponents in Wrestling, smash the ball in Tennis! Quick reflexes, fast button presses and accurate controls are required to make the highest rankings and succeed in 24 different achievements. Compete in solo events or try multiple event tournaments! The following 12 sports are included: 100m Sprint Pro Wrestling Skeet Shooting Baseball Speed Skating Fencing Rugby Tennis Soccer Archery Hammer Throw Table Tennis' FROM games WHERE igdb_id = 84633 ON CONFLICT (game_id, language_code) DO NOTHING;
