INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Outbreak', 'Explore a nightmarish environment, scrounge for supplies, and battle the undead in Outbreak -- an online co-op survival horror game. The clock never stops as you attempt to manage an extremely limited inventory with a murderous horde on the hunt. Choose between acquiring additional weapons, healing items, or necessary tools for progression. You have only one life. Make it count!' FROM games WHERE igdb_id = 26909 ON CONFLICT (game_id, language_code) DO NOTHING;
