INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mario Kart 8 Deluxe', 'Hit the road with the definitive version of Mario Kart 8 and play anytime, anywhere! Race your friends or battle them in a revised battle mode on new and returning battle courses. Play locally in up to 4-player multiplayer in 1080p while playing in TV Mode. Every track from the Wii U version, including DLC, makes a glorious return. Plus, the Inklings appear as all-new guest characters, along with returning favorites, such as King Boo, Dry Bones, and Bowser Jr.!' FROM games WHERE igdb_id = 26764 ON CONFLICT (game_id, language_code) DO NOTHING;
