INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Circuit Warz', 'Circuit Warz is an indie action game that tests your understanding of basic electronic circuits. To complete the game successfully you need to understand the operation of Series Parallel Resistor circuits, Resistor Capacitor (RC) filters, Graetz Bridges, Wheatstone bridges, Weighted summing amplifiers, Transistor switches and Oscillator circuits.' FROM games WHERE igdb_id = 38772 ON CONFLICT (game_id, language_code) DO NOTHING;
