INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('shinai-naru-kodoku-to-kunou-e', 350600, '2017-05-06', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobapc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxnaj.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shinai Naru Kodoku to Kunou e', 'Uchida Kisaki, Nako Ryuusuke, and Tomiya Umi—three college students trying to make sense of modern life. They were stuck. Dreams, goals, jobs, relationships, family… And then there were their own personalities, their thoughts, their very selves. The present felt out of reach, and the future even more so. At the end of a desperate internet search for "counselor," on the 39th page of results, they stumbled onto something. A painfully simple website, but with bold, confident claims. And for some reason, it was free. This was how they met Tachibana Makoto, a counselor who went by simply "Mako." What would change in their hearts? What choices would they make? Where would they end up? Let’s see where it all leads.' FROM games WHERE igdb_id = 350600 ON CONFLICT (game_id, language_code) DO NOTHING;
