INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Miner Meltdown', 'Miner Meltdown is an action-packed team-based multiplayer game. Scour the map for minerals, upgrade your gear, and attempt to blow up the opposing team all the while avoiding monsters, traps, and environmental pitfalls along the way. Maps are randomly generated and 100% destructible, so every match is a fully unique, fast-paced, and chaotic affair.' FROM games WHERE igdb_id = 33936 ON CONFLICT (game_id, language_code) DO NOTHING;
