INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Legend of Heroes: Trails of Cold Steel III', 'The Legend of Heroes: Trails of Cold Steel III is the eighth installment in the main Trails series, serving as a direct sequel to the events of The Legend of Heroes: Trails of Cold Steel II. The game follows Rean Schwarzer, now a military professor, as well as his students, and the rest of his military school friends from the prior two entries, notably exploring subjects such as the mysterious origin''s of Rean''s birth, and what others have been up to since the events of the prior games.' FROM games WHERE igdb_id = 26564 ON CONFLICT (game_id, language_code) DO NOTHING;
