INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VRChat', 'In VRChat there is something around every corner that will delight, thanks to the power of true user generated content. Jump into hundreds of awe-inspiring environments and meet unique avatars every day. Watch a movie on the moon. Ride the Titanic. Step into a new world every time you come online. In VRChat, you are one of us. Enjoy your stay.' FROM games WHERE igdb_id = 33615 ON CONFLICT (game_id, language_code) DO NOTHING;
