INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Long Dark', 'Welcome to The Long Dark, the innovative exploration-survival experience Wired magazine calls "the pinnacle of an entire genre". The game is a thoughtful, exploration-survival experience that challenges solo players to think for themselves as they explore an expansive frozen wilderness in the aftermath of a geomagnetic disaster. There are no zombies but only you, the cold, and all the threats Mother Nature can muster.' FROM games WHERE igdb_id = 8347 ON CONFLICT (game_id, language_code) DO NOTHING;
