INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Am I Part of the Problem?', 'Did you hurt someone? Are you having trouble coming to terms with it? Are you unsure what to do next? Am I Part Of The Problem? will walk you through what you did, how and when to apologize, and most importantly, how to make amends.' FROM games WHERE igdb_id = 182914 ON CONFLICT (game_id, language_code) DO NOTHING;
