INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Truck Simulator PRO 2', 'In Truck Simulator Pro 2 build up your transporting empire driving huge and powerful trucks on American soil. An enormous open world with thousands of miles of precisely mapped roads awaits for your arrival. Admire carefully designed viaducts, huge road intersections and bridges as well as more diversified routes amongst hills, valleys, deserts and swamps..' FROM games WHERE igdb_id = 88947 ON CONFLICT (game_id, language_code) DO NOTHING;
