INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Night in Tokyo', 'Last Night in Tokyo is a short kinetic visual novel based on real life LGBTQIA+ events and establishments in Tokyo, Japan. From the eyes of a tourist on her last day in the city, you''ll get to experience a small taste of what the Japanese queer scene has to offer. We hope that you''ll enjoy the story and that you''ll also find that it scratches your interests to learn even more about its topics.' FROM games WHERE igdb_id = 148050 ON CONFLICT (game_id, language_code) DO NOTHING;
