INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Last Tale', 'For a whole year the monkey rules the world, but the moment came when she needed to leave. The monkey did not want to part with her throne, and then she decided that if no one celebrates the new year, next year will not come. Therefore, she decided to spoil all the holiday. A mellow monkey sent a magic charm on a toy in a bag of Santa Claus.' FROM games WHERE igdb_id = 29129 ON CONFLICT (game_id, language_code) DO NOTHING;
