INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fruit Arranger', 'Fruit Arranger is a fun puzzle game where you have to place fruits on a 9x9 table. When you match 3 in a same row or column the last fruit placed will transform into another fruit. Your goal is to place as many fruits as possible without getting stuck. OVER 100 ACHIEVEMENTS to gain' FROM games WHERE igdb_id = 29863 ON CONFLICT (game_id, language_code) DO NOTHING;
