INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Five Nights at Freddys: Final Hours', 'Welcome to your new summer job at Freddy Fazbear''s Pizza, where kids and parents alike come for entertainment and food as far as the eye can see! The main attraction is Freddy Fazbear, of course; and his two friends. They are animatronic robots, programmed to please the crowds! The robots'' behavior has become somewhat unpredictable at night however, and it was much cheaper to hire you as a security guard than to find a repairman.' FROM games WHERE igdb_id = 340120 ON CONFLICT (game_id, language_code) DO NOTHING;
