INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Space Hunted', 'You are Jade Hunter, an intergalactic treasure hunter. While traveling past an uncharted planet, your ship was shot down. Now Jade is an intruder, an alien, on this uncharted planet, and is being hunted down. Your mission is to survive and escape the planet! Travel through 128 levels! Avoid and defeat enemies to survive! Collect powers to ensure your survival! Do you have what it takes to survive in Space Hunted? Or will you be hunted down?' FROM games WHERE igdb_id = 84892 ON CONFLICT (game_id, language_code) DO NOTHING;
