INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Percy the Penguin Saves Christmas', 'Percy the Penguin is a platformer designed to mimic old arcade games, such as "Mario Bros." and "Bubble Bobble". Throw snowballs at rogue Christmas toys to stun them, and touch them to wrap them in a present. Once every enemy is wrapped up, continue on to the next level! For 1-2 players locally, on PC and Mac.' FROM games WHERE igdb_id = 78548 ON CONFLICT (game_id, language_code) DO NOTHING;
