INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'VR Golf Online', 'When Golf meets the limitless possibilities of Virtual Reality, the green is only inches away! Practice your swing and develop your techniques to improve your handicap. Step onto one of the 36 realistic holes, with additional courses planned for the near future. VR Golf Online can be played as a singleplayer (practice) mode, against AI opponents, or against your friends for a game of local and/or online multiplayer. Compete and become the golf pro you''ve always wanted to be!' FROM games WHERE igdb_id = 29851 ON CONFLICT (game_id, language_code) DO NOTHING;
