INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'How to Fool a Liar King', 'Regina, the heroine of our story, finds herself magically transported to the land of Eroolia, clueless about how to return home. She meets Juli and his companions who are in the middle of a journey to Laarz, a country of cat people. Will she find out how to get back home? Or will she fall in love before that happens? Find out in this game!' FROM games WHERE igdb_id = 72344 ON CONFLICT (game_id, language_code) DO NOTHING;
