INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ojou-sama no Hanbun wa Renai de Dekiteimasu!', 'The pretty boy Hajime is an agent of a large secret organization, who was asked by the boss one day to do the impossible. His mission was to infiltrate Houshou Girl’s Academy, where only pure maidens are allowed, and to claim the title of the greatest lady: ‘Highness’. Thus, he traded in his weapon for lipstick to become an agent of matchless beauty. What is the purpose of this strange mission?' FROM games WHERE igdb_id = 328216 ON CONFLICT (game_id, language_code) DO NOTHING;
