INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spark the Electric Jester', 'Spark the electric jester is an action/platformer video game heavily based on best classics from the 16-bit era from both sides of the aisle. You play as Spark, an electric jester frustrated by the loss of his job! On one beautiful day, robots decided to take over the world. Seeing as Spark’s job was taken by a robot, he decided this was the perfect opportunity for his revenge! Spark will have to travel through the world and be engulfed in high-speed thrills and tons of action against the robots and the one who has taken his job.' FROM games WHERE igdb_id = 28134 ON CONFLICT (game_id, language_code) DO NOTHING;
