INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Void', 'Void is a visual novel themed around espionage and revenge. You play as Arthur Woods, a man seeking revenge from the death of his loved one, forging himself into a deadly assassin. Along the way, you will meet people who may (or may not) be your allies, as you try to untangle the web of lies and intrigue surrounding your girlfriends death.' FROM games WHERE igdb_id = 84103 ON CONFLICT (game_id, language_code) DO NOTHING;
