INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virus of Survivors: Life Simulator', 'Virus of Survivors: Life Simulator is a brand new simulation game, where you can explore the human body and fight with viruses and bacteria. The game begins on the emergency class, where a sick man lies, who waiting for a medicine of vital… You will be the medicine capsule which can redound the healing, and you enter into the human body by infusion and you have to begin the fight with the micro world to save your patient life!' FROM games WHERE igdb_id = 56669 ON CONFLICT (game_id, language_code) DO NOTHING;
