INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'FallenCore', 'FallenCore is a 2D platformer about Ardi the repair android, who arrived on a huge space station to fix the malfunctioned central core of the ship. After the breakdown, many on-board mechanisms became dangerous and can easily kill the character, as well as the robots "went crazy" and arranged a hunt for Ardi not to let it get to the core.' FROM games WHERE igdb_id = 75101 ON CONFLICT (game_id, language_code) DO NOTHING;
