INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chapters: Interactive Stories', 'Chapters: Interactive Stories will bring a unique and fun twist to choose your own story adventures. Whether you''re an avid reader of drama, comedy, fantasy, sci-fi, young adult, romance, or even a gamer, you''ll love making choices in this interactive story game! Read through pages and pages of fun interactive stories that fit your mood, from romance to suspense!
