INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('taima-miko-yuugi', 68673, '2017-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/zzcsh3mjw2pceykqyjp6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/di9da7vattikyqggch2d.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Taima Miko Yuugi', '現在日本の地方の小さな町を舞台とした、戦闘中H特化型女主人公18禁RPGです。自らを正義の退魔士と名乗る、お調子者の退魔士『セツナ』となって、突如、町に復活した魔物と戦っていきます。セツナを襲う魔物の様々な攻撃、息つく間もない戦闘H。そして本作では、『それら全てが、戦闘中のセツナの立ち絵に反映されます』' FROM games WHERE igdb_id = 68673 ON CONFLICT (game_id, language_code) DO NOTHING;
