INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'TankBlitz', 'TankBlitz is a brutal run and gun tank game with four playable tanks, each having access to four unique weapons and dozens of upgrades. You blast your way through twelve handcrafted levels crawling with over 50 different kinds of enemies, and numerous challenging bossfights.' FROM games WHERE igdb_id = 28791 ON CONFLICT (game_id, language_code) DO NOTHING;
