INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Murder In Tehran''s Alleys 2016', 'This is the story of the time when narcotics impair the brain; the time when a father’s hallucination becomes the dawn of his family’s demise by slicing them into pieces for a sin they have not committed; the time when revenge is the only reason to live. A series of violent and ruthless murders committed on the pretext of Deadly Sins (religion) brings Faramarz Afshar, a 32-year-old detective, into a case for which no easy conclusion can be found. "Murder in Tehran’s Alleys 2" is a tribute to David Fincher’s "Se7en".' FROM games WHERE igdb_id = 40858 ON CONFLICT (game_id, language_code) DO NOTHING;
