INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('survivalizm-the-animal-simulator', 28082, '2017-04-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co24v3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4ndl.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survivalizm - The Animal Simulator', 'You are a wild spirit who is capable of coming into existence as any animal in a realistically replicated forest, where rules of the wild prevail. Fight or Flight, Mate, Grow your Herd, Leave a Legacy. Here you must survive, using your wits, strength, bravery and cunningness. Grow up from a cub, find a home and mate, have kids and raise them, leave a legacy and rule the forest.' FROM games WHERE igdb_id = 28082 ON CONFLICT (game_id, language_code) DO NOTHING;
