INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'No World Dreamers: Sticky Zeitgeist', 'No World Dreamers: Sticky Zeitgeist is an episodic game-comic about a town plagued by space waste, and the girls working to clean it. After a satellite in orbit is destroyed, the company INNOCENT tasks itself with scavenging for the fallen parts, placing its workers at risk for radiation. In the first episode, players meet Ever, Brava, Chalcedony, and Agate, animal and robot girls who work at INNOCENT. Players quickly immerse themselves in the culture of No World Dreamer’s swamp world.' FROM games WHERE igdb_id = 354753 ON CONFLICT (game_id, language_code) DO NOTHING;
