INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Containment Initiative', 'Containment Initiative is a Virtual Reality shooter for the HTC Vive. Featuring a realistic weapon handling and reloading system, take on the infected horde alone or with a friend assisting you from the PC in multiple mission types which feature both stand in place shooting and locomotion enabled areas.' FROM games WHERE igdb_id = 31348 ON CONFLICT (game_id, language_code) DO NOTHING;
