INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Boratium Wars', 'Boratium Wars is fast paced 2d Space Shooter. Collect Boratium from Asteroids, avoiding enemy ships, void meteors, space mines, and more. Use your earnings to upgrade your ship, buy new ships, or just sit on the wealth to buy lives to reach the Galactic Top Pilot list. Tons of mindless fun!' FROM games WHERE igdb_id = 74134 ON CONFLICT (game_id, language_code) DO NOTHING;
