INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Cubeshift', 'Cubeshift is an infinite arcade puzzler. Help guide the falling square using sliders! As the square falls, it will land on a layer of sliders which can be manipulated to guide the square past each layer. Watch out for the spikes, touching the top of those or causing the square to lag behind will result in a game over!' FROM games WHERE igdb_id = 54542 ON CONFLICT (game_id, language_code) DO NOTHING;
