INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sono Hanabira ni Kuchizuke wo: Michael no Otome-tachi', 'Sono Hanabira ni Kuchizuke wo: Michael no Otome-tachi is an adult visual novel and the eleventh game in the Sono Hanabira ni Kuchizuke wo series of games. The game introduces the new couple of Azumi Risa and Ayase Miya. All couples from Fuguriya''s prior A Kiss For The Petals releases are also featured and have their own storylines that are tangential to the main story featuring Risa and Miya.' FROM games WHERE igdb_id = 12263 ON CONFLICT (game_id, language_code) DO NOTHING;
