INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Waiting Room', 'The Waiting Room is a standalone mini-game taking place between Welcome to the game and the soon to be released Welcome to the Game 2. Expanding further on the gameplay style of Welcome to the Game, The Waiting Room is a horror puzzle experience that takes you into the other side of the deep web. The game brings you back to the familiar experience of hunting for keys while bringing a whole new set of mechanics to the world around you in an all new environment. Stay vigilant.' FROM games WHERE igdb_id = 74695 ON CONFLICT (game_id, language_code) DO NOTHING;
