INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Gallery: Episode 2 - Heart of the Emberstone', 'After receiving your Gauntlet, a mysterious new power in the palm of your hand, you must travel to Ember, a long-forgotten world whose past holds many secrets. Find Elsie, uncover the history of Ember, and reveal the true intentions of the dark figure in the Starseed.' FROM games WHERE igdb_id = 68173 ON CONFLICT (game_id, language_code) DO NOTHING;
