INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('defenders-of-the-realm-vr', 36709, '2017-05-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2arj.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mime3zmq3n23wwzpr2ms.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Defenders of the Realm VR', 'There is no futuristic weapons and no fancy-shmancy magic powers. In this brutal world, the only power you have is the badass crossbow in your hands and the myriad traps at your disposal. Put your limited resources to good use and repel the barbaric goblin invasion.  There are no rules. You have just one mission: destroy them all. You can burn, slash, nail, maim, pierce, sever or shoot''em in the head. Remember, if just one foe is left alive, the future of the realm is in jeopardy.  When you put on your VR headset and face these savage villains on the field of battle, you will encounter unprecedented brutality and ruthlessness. Your foes might seem innocent, but when they chase you into a corner and try to bash your head in, you will surely forgo any compassion you might have left for them. Pick up your weapon, ready your traps, and prepare for war. There is only one goal: kill them all!' FROM games WHERE igdb_id = 36709 ON CONFLICT (game_id, language_code) DO NOTHING;
