INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tank Battle: Pacific', 'Capture the experience of being a tank commander in the Pacific Theatre in World War Two. Fight battles between Japan, France, China, Russia, British Commonwealth and The United States of America. The game has a wide range of features from the tank battles of Northern Manchuria to the battlefields of Burma and the landings on the Pacific Islands. The game even includes a what-if scenario for Operation Olympic, the invasion of the Japanese homelands.' FROM games WHERE igdb_id = 44090 ON CONFLICT (game_id, language_code) DO NOTHING;
