INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unknown Pharaoh', 'Unknown Pharaoh will immerse you in an incredible adventure. You will take on the role of an archaeologist exploring an ancient Egyptian pyramid. Decipher genuine ancient Egyptian hieroglyphs. Discover ancient Egyptian artifacts. Watch out for traps. This game uses arm swings locomotion. This game takes approximately 50 to 60 minutes to complete.' FROM games WHERE igdb_id = 29887 ON CONFLICT (game_id, language_code) DO NOTHING;
