INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Arena an Age of Barbarians story', 'A non-stop action game, completely skill based. Immerse yourself into an incredible adventure in a world inspired by the 80s’ Sword & Sorcery fantasy. Frantic action, brutal fighting, monsters, romance, and plenty of Heavy Metal rhythms.' FROM games WHERE igdb_id = 30077 ON CONFLICT (game_id, language_code) DO NOTHING;
