INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caveman Warriors', 'Jump back in time and free your inner caveman. Smash heads in Caveman Warriors, a local cooperative 2D platformer game. Play solo, with one, two or three friends. Work together to become unstoppable! Choose one of the playable characters, but don’t worry! You can change your character at anytime in the game and play with them all! Each level has different enemies, watch out as they can catch you unguarded.' FROM games WHERE igdb_id = 29250 ON CONFLICT (game_id, language_code) DO NOTHING;
