INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AI Escort', 'This is an otome visual novel, it is a satire on highly developed industrial technology in Japan, in which the decline of human civilization, moral decays, and low birth rate gets out of control under the huge social pressure. Someday, Ruri picked up Aizen. Ruri stayed up all night to repair Aizen, but due to his former hostess treating him horribly, his body function could only last for five days.' FROM games WHERE igdb_id = 96421 ON CONFLICT (game_id, language_code) DO NOTHING;
