INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beat Cop', 'A retro, pixel art style adventure in New York, inspired by 80’s cop shows. You are Jack Kelly and you’ve been framed into murder. Now as a regular beat cop you have to find out, who did that. Expect thick crime story, a lot of black humour and all the other things you can find on the streets of Brooklyn.' FROM games WHERE igdb_id = 18860 ON CONFLICT (game_id, language_code) DO NOTHING;
