INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chimpology', 'It''s the year 1999. The internet is really slow. Some people might try to tell you that it''s because the modem line just can''t handle more speed... but don''t trust them, it was all chimpanzees. Typing the pictures out, bit by bit. And you''re one of them.' FROM games WHERE igdb_id = 37391 ON CONFLICT (game_id, language_code) DO NOTHING;
