INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hakuoki: Kyoto Winds - Deluxe Edition', 'Includes: - Hakuoki: Kyoto Winds - Winds Treasure Box DLC: A collection of six previously-untold stories. - OST: 20 tracks to immerse yourself in the battles fought and the emotions felt in Kyoto. - Event Scene Collection: 17 pages of gorgeous event scenes. - PC Wallpaper: Add some beauty to your screen with 4 wallpapers. - Mobile Wallpaper: Protect your mobile device with any 12 of your favorite bachelors. - Character Art Collection: 13 pages showing rough sketches and full-color artwork of the beautiful characters.' FROM games WHERE igdb_id = 243920 ON CONFLICT (game_id, language_code) DO NOTHING;
