INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Leaving Lyndow', 'Leaving Lyndow is a short, first-person exploration adventure game, set in the Eastshade universe. It''s Clara''s last day on the island where she grew up. With high honors, she''s graduated and fulfilled her childhood dream of joining the Guild of Maritime Exploration. She needs to complete preparations, visit her favorite places, and say her goodbyes before leaving on a journey she may not return from. *dangerous journey not included*' FROM games WHERE igdb_id = 27139 ON CONFLICT (game_id, language_code) DO NOTHING;
