INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ikemen Vampire: Temptation in the Dark', 'The game takes place in late 19th century France where you, the player, have been transported to from the 21st century. You''re stuck in a mansion full of some of the greatest historical figures of all time for a month until you can go back to your own era, but there''s a catch - every single one of them is a vampire. There''s only one rule for you during your stay, don''t fall in love.' FROM games WHERE igdb_id = 225536 ON CONFLICT (game_id, language_code) DO NOTHING;
